def genIfElse(x, y, z):
  global regs, reguse
  putLab(y)
  regs, reguse = set(GPregs), {}

def genWhile():
  global regs, reguse
  lab = newLabel()
  putLab(lab)
  regs, reguse = set(GPregs), {}
