Procedure `loadItem(x)` generates code for loading `x` on the expression stack, assuming `x` is global `Var`, local `Var`, stack `Var`, memory `Var`, local `Ref`, stack `Ref`, `Const`.

```python
def loadItem(x):
  if type(x) == Var:
    if x.lev == 0:
      asm.append('global.get $' + x.name)  # global Var
    elif x.lev == curlev:
      asm.append('local.get $' + x.name)  # local Var
    elif x.lev == -2:  # memory Var
      asm.append('i32.const ' + str(x.adr))
      asm.append('i32.load')
    elif x.lev != -1:
      mark('WASM: var level!')  # already on stack if lev == -1
  elif type(x) == Ref:
    if x.lev == -1:
      asm.append('i32.load')
    elif x.lev == curlev:
      asm.append('local.get $' + x.name)
      asm.append('i32.load')
    else:
      mark('WASM: ref level!')
  elif type(x) == Const:
    asm.append('i32.const ' + str(x.val))
```

Procedure `genAssign(x, y)` generates code for `x := y`, provided `x` is `Var`, `Ref` and `y` is `Var`, `Ref`.

```python
def genAssign(x, y):
  if type(x) == Var:
    if x.lev == -2:
      asm.append('i32.const ' + str(x.adr))
    loadItem(y)
    if x.lev == 0:
      asm.append('global.set $' + x.name)
    elif x.lev == curlev:
      asm.append('local.set $' + x.name)
    elif x.lev == -2:
      asm.append('i32.store')
    else:
      mark('WASM: level!' + str(x.name) + str(x.lev) + 'curlev' + str(curlev))
  elif type(x) == Ref:
    if x.lev == curlev:
      asm.append('local.get $' + x.name)
    loadItem(y)
    asm.append('i32.store')
  else:
    mark('WASM: assignment?')
