# return the list of tuples
# (name, type)
# typedIds can take in a class (fromClass)
# to represent the idents are attributes of the class
# and will be added to the symbol table
def typedIds():
  global Debug
  if Debug:
    printMark('typedIds start')
  # list of newly created ident in tuples
  newIdents = []
  if SC.sym == IDENT:
    tid = [SC.val]
    getSym()
  else:
    mark('identifier expected')
  while SC.sym == COMMA:
    getSym()
    if SC.sym == IDENT:
      tid.append(SC.val)
      getSym()
    else:
      mark('identifier expected')
  if SC.sym == COLON:
    getSym()
  else:
    mark("':' expected")
  tp = typ().val
  for i in tid:
    newDecl(i, Var(tp))
    # add the tuple to the result list
    newIdents.append((i, tp))
  while SC.sym == COMMA:
    getSym()
    if SC.sym == IDENT:
      tid = [SC.val]
      getSym()
    else:
      mark('identifier expected')
    while SC.sym == COMMA:
      getSym()
      if SC.sym == IDENT:
        tid.append(SC.val)
        getSym()
      else:
        mark('identifier expected')
    if SC.sym == COLON:
      getSym()
    else:
      mark("':' expected")
    tp = typ().val
    for i in tid:
      newDecl(i, Var(tp))
      # add the tuple to result list
      newIdents.append((i, tp))
  if Debug:
    printMark('typedIds end')
  return newIdents
