    if type(x) == Const:
      newDecl(ident, x)
    else:
      mark('expression not constant')
  while SC.sym == TYPE:
    getSym()
    if SC.sym == IDENT:
      ident = SC.val
      getSym()
    else:
      mark('type name expected')
    if SC.sym == EQ:
      getSym()
    else:
      mark('= expected')
    x = typ()
    newDecl(ident, x)  #  x is of type ST.Type
  #'Class' ident
  while SC.sym == CLASS:
    getSym()
    if SC.sym == IDENT:
      ident = SC.val
      getSym()
    else:
      mark('class name expected')
    # below takes care of extends,
    # ext: name of the class, "" if no extends
    ext = ''
    if SC.sym == EXTENDS:
      getSym()
      if SC.sym == IDENT:
        ext = SC.val
        getSym()
      else:
        mark('extends class name expected')
    currentClass = Class('', ext)
    newDecl(
      ident, currentClass
    )  # add empty class with name ident into symbol table
    classBody(ident, ext, currentClass)
  start = len(topScope())
  while SC.sym == VAR:
    getSym()
    typedIds()
  while SC.sym == OBJECT:
    # objects are declared as Var, with type (.tp) being the Class() created
    getSym()
    typedIds()
    # print("Object detected, current SC.val::", SC.val)
  # ST.printSymTab()
  varsize = allocVar(topScope(), start)
  while SC.sym == PROCEDURE:
    getSym()

classBody(ident, ext, currentClass)
  start = len(topScope())
  while SC.sym == VAR:
    getSym()
    typedIds()
  while SC.sym == OBJECT:
    # objects are declared as Var, with type (.tp) being the Class() created
    getSym()
    typedIds()
    # print("Object detected, current SC.val::", SC.val)
  # ST.printSymTab()
  varsize = allocVar(topScope(), start)
  while SC.sym == PROCEDURE:
    getSym()
    if SC.sym == IDENT:
      ident = SC.val
      getSym()
    else:
      mark('procedure name expected')
    newDecl(ident, Proc([], []))  #  entered without parameters
    sc = topScope()
    openScope()  # new scope for parameters and body
    if SC.sym == LPAREN:
      getSym()
    else:
      mark('( expected')
    if SC.sym == IDENT:
      typedIds()
    fp = topScope()
    if SC.sym == RPAREN:
      getSym()
    else:
      mark(') expected')
    d = len(fp)
    if SC.sym == RARROW:
      getSym()
      if SC.sym == LPAREN:
        getSym()
      else:
        mark('( expected')
      typedIds()
      if SC.sym == RPAREN:
        getSym()
      else:
        mark(') expected')
    sc[-1].par, sc[-1].res = fp[:d], fp[d:]  #  procedure parameters updated
    parsize = CG.genProcStart(ident, fp[:d], fp[d:])
    body(ident, parsize)
    closeScope()  #  scope for parameters and body closed
  if Debug:
    printMark('declarations end')
  return varsize
