# return a Proc type
def findMethod(name):
  # e.g.   j.setPrintSIN
  nameSplit = name.split('.')
  if len(nameSplit) != 2:
    mark('undeinfed class identifier' + name)
  varName = nameSplit[0]  # e.g. j
  metName = nameSplit[1]  # e.g. setPrinSIN
  for l in symTab:
    found = False
    for e in l:
      if e.name == varName:
        found = True
        cl = e.tp
        assert type(cl) == Class
        break
    if found:
      break
  if not found:
    mark('undefined object identifier' + varName)
  while True:
    # class.methodName
    procName = cl.name + '.' + metName
    for l in symTab:
      for e in l:
        if procName == e.name:
          assert type(e) == Proc
          return e
    # if not found, might be base class method
    found = False
    for l in symTab:
      for e in l:
        if cl.extends == e.name:
          assert type(e) == Class
          cl = e
          found = True
          break
      if found:
        break
    if not found:
      mark('Method not found ' + name)

