}

int main(int argc, char *argv[]) {
    int numcust = atoi(argv[1]);
    long i;
    pthread_t b, c[numcust];
    pthread_create(&b, NULL, &villagebarber, NULL);
    for (i = 0; i < numcust; i++) pthread_create(&c[i], NULL, &customer, (void *) i);
