## Asynchronous Message Passing

```python
%%writefile sorter.go

package main

import ("fmt"; "time"; "math/rand")

const EOS = -1

const N = 1 << 17  // N = 2**16
const R = 2000     // number of repetitions

func printer(in chan int) {
    for {//j := 0; j < R * (N + 1); j++ {
        v := <- in
        if v == EOS {println()
        } else {print(v, " ")
        }
    }
}

func merger(in1, in2 chan int, out chan int) {
    for {
        v1, v2 := <- in1, <- in2
        for v1 != EOS || v2 != EOS {
            if v1 != EOS && v2 != EOS {
                if v1 <= v2 {out <- v1; v1 = <- in1
                } else {out <- v2; v2 = <- in2
                }
            } else if v1 != EOS {
                out <- v1; v1 = <- in1
            } else {
                out <- v2; v2 = <- in2
            }
        }
        out <- EOS
    }
}

func main() {
    start := time.Now()

    var c [2 * N] chan int
    for i := range c {c[i] = make(chan int, 4)}

    for i := 1; i < N; i++ {go merger(c[i * 2], c[i * 2 + 1], c[i])}

    go func () {
        for j := 0; j < R; j++ {
            for i := N; i < 2 * N; i++ {c[i] <- rand.Int()%100; c[i] <- EOS}
        }
    } ()

    //printer(c[1]) // comment out one of these lines
    for k := 0; k < R; k++ {<- c[1]}

    fmt.Println(time.Since(start))
}
```

